mapper.select:
select ifnull(sum(r.sale_amount), 0)
from fin_sale_record r
 r.del_flag = '0'
    and r.dept_id = #{deptId}

        and r.sale_date >= #{startTime}


        and r.sale_date <= #{endTime}

select count(1)
from fin_sale_record r
 r.del_flag = '0'
    and r.dept_id = #{deptId}

        and r.sale_date >= #{startTime}


        and r.sale_date <= #{endTime}

select ifnull(sum(r.total_quantity), 0)
from fin_sale_record r
 r.del_flag = '0'
    and r.dept_id = #{deptId}

        and r.sale_date >= #{startTime}


        and r.sale_date <= #{endTime}

select ifnull(sum(e.expense_amount), 0)
from fin_expense e
 e.del_flag = '0'
    and e.dept_id = #{deptId}

        and e.expense_date >= #{startTime}


        and e.expense_date <= #{endTime}

select ifnull(sum(e.expense_amount), 0)
from fin_expense e
 e.del_flag = '0'
    and e.status = '0'
    and e.dept_id = #{deptId}

        and e.expense_date >= #{startTime}


        and e.expense_date <= #{endTime}

select ifnull(sum(a.advance_amount), 0)
from fin_advance a
 a.del_flag = '0'
    and a.status = '0'
    and a.dept_id = #{deptId}

        and a.advance_date >= #{startTime}


        and a.advance_date <= #{endTime}

select
date_format(r.sale_date, '%x-W%v') date_format(r.sale_date, '%Y-%m') date_format(r.sale_date, '%Y-%m-%d') as dateStr, ifnull(sum(r.sale_amount), 0) as salesAmount from fin_sale_record r r.del_flag = '0' and r.dept_id = #{deptId}
and r.sale_date >= #{startTime}
and r.sale_date <= #{endTime}
group by
date_format(r.sale_date, '%x-W%v') date_format(r.sale_date, '%Y-%m') date_format(r.sale_date, '%Y-%m-%d')
order by dateStr

select
date_format(e.expense_date, '%x-W%v') date_format(e.expense_date, '%Y-%m') date_format(e.expense_date, '%Y-%m-%d') as dateStr, ifnull(sum(e.expense_amount), 0) as expenseAmount from fin_expense e e.del_flag = '0' and e.dept_id = #{deptId}
and e.expense_date >= #{startTime}
and e.expense_date <= #{endTime}
group by
date_format(e.expense_date, '%x-W%v') date_format(e.expense_date, '%Y-%m') date_format(e.expense_date, '%Y-%m-%d')
order by dateStr

select e.expense_type as categoryName,
       ifnull(sum(abs(e.expense_amount)), 0) as amount
from fin_expense e
 e.del_flag = '0'
    and e.dept_id = #{deptId}

        and e.expense_date >= #{startTime}


        and e.expense_date <= #{endTime}


group by e.expense_type
order by amount desc

select 'EXPENSE' as itemType, e.expense_id as itemId, e.expense_no as itemNo, e.expense_amount as amount, e.status as status, e.expense_date as occurTime from fin_expense e e.del_flag = '0' and e.status = '0' and e.dept_id = #{deptId}
and e.expense_date >= #{startTime}
and e.expense_date <= #{endTime}
order by e.expense_date desc

select 'ADVANCE' as itemType, a.advance_id as itemId, a.advance_no as itemNo, a.advance_amount as amount, a.status as status, a.advance_date as occurTime from fin_advance a a.del_flag = '0' and a.status = '0' and a.dept_id = #{deptId}
and a.advance_date >= #{startTime}
and a.advance_date <= #{endTime}
order by a.advance_date desc

select ifnull(sum(r.sale_amount), 0)
from fin_sale_record r
where r.del_flag = '0'
  and r.dept_id = #{deptId}
  and r.sale_date >= #{startTime}
  and r.sale_date <= #{endTime}

select ifnull(sum(e.expense_amount), 0)
from fin_expense e
where e.del_flag = '0'
  and e.dept_id = #{deptId}
  and e.expense_date >= #{startTime}
  and e.expense_date <= #{endTime}

select d.dept_id as deptId, d.dept_name as deptName, ifnull(s.total_sales, 0) as totalSales, ifnull(s.sale_count, 0) as saleCount, ifnull(s.sale_quantity, 0) as saleQuantity, ifnull(e.total_expense, 0) as totalExpense, ifnull(e.unverified_expense, 0) + ifnull(a.unverified_advance, 0) as unverifiedAmount from sys_dept d left join ( select dept_id, sum(sale_amount) as total_sales, count(1) as sale_count, sum(total_quantity) as sale_quantity from fin_sale_record
del_flag = '0' and dept_id in #{deptId} and sale_date >= #{startTime} and sale_date <= #{endTime}
group by dept_id ) s on d.dept_id = s.dept_id left join ( select dept_id, sum(expense_amount) as total_expense, sum(case when status = '0' then expense_amount else 0 end) as unverified_expense from fin_expense
del_flag = '0' and dept_id in #{deptId} and expense_date >= #{startTime} and expense_date <= #{endTime}
group by dept_id ) e on d.dept_id = e.dept_id left join ( select dept_id, sum(advance_amount) as unverified_advance from fin_advance
del_flag = '0' and status = '0' and dept_id in #{deptId} and advance_date >= #{startTime} and advance_date <= #{endTime}
group by dept_id ) a on d.dept_id = a.dept_id where d.dept_id in #{deptId}

select r.dept_id as deptId, ifnull(sum(r.sale_amount), 0) as memberSales
from fin_sale_record r

    r.del_flag = '0'
    and r.sale_no in (select sr.sale_no from fin_sale_record sr where sr.del_flag = '0' and sr.remark like '%member%')
    and r.dept_id in
    #{deptId}
     and r.sale_date >= #{startTime} 
     and r.sale_date <= #{endTime} 

group by r.dept_id
